package com.sofratesa.sofcal;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.webkit.*;import android.widget.*;import android.util.Base64;import java.io.*;import java.util.*;import org.json.JSONObject;
public class MainActivity extends Activity {
 private static final String ORIGIN="https://sofcal.local";
 private WebView web; private ValueCallback<Uri[]> picker; private String pendingReturn; private boolean ready=false; private byte[] pendingSave;
 @Override public void onCreate(Bundle state){super.onCreate(state);web=new WebView(this);web.setFitsSystemWindows(true);setContentView(web);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(true);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setSupportZoom(false);s.setMediaPlaybackRequiresUserGesture(true);web.addJavascriptInterface(new Bridge(),"SofcalAndroid");
 web.setWebViewClient(new WebViewClient(){
  @Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){Uri u=r.getUrl();if(!"sofcal.local".equals(u.getHost()))return null;String path=u.getPath();if(path==null||path.contains(".."))return missing();if(path.equals("/"))path="/index.html";try{String mime=path.endsWith(".html")?"text/html":path.endsWith(".js")?"application/javascript":path.endsWith(".json")||path.endsWith(".webmanifest")?"application/json":path.endsWith(".css")?"text/css":path.endsWith(".pdf")?"application/pdf":path.endsWith(".xlsx")?"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet":path.endsWith(".png")?"image/png":"application/octet-stream";return new WebResourceResponse(mime,"UTF-8",200,"OK",headers45(),getAssets().open("web"+path));}catch(IOException e){return missing();}}
  @Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){Uri u=r.getUrl();if("sofcal.local".equals(u.getHost())&&"https".equals(u.getScheme()))return false;if(r.isForMainFrame())external(u);return true;}
  @Override public void onPageFinished(WebView v,String url){if(url.startsWith(ORIGIN+"/")){ready=true;deliverReturn();}}
 });
 web.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> callback,FileChooserParams params){if(picker!=null)picker.onReceiveValue(null);picker=callback;try{startActivityForResult(params.createIntent(),61);}catch(Exception e){picker.onReceiveValue(null);picker=null;message("No se encontró una aplicación para seleccionar archivos.");}return true;}});
 captureReturn(getIntent());web.loadUrl(ORIGIN+"/index.html");}
 private Map<String,String> headers45(){Map<String,String> h=new HashMap<>();h.put("Cache-Control","no-cache");h.put("Content-Security-Policy","frame-src 'none'; object-src 'none'; base-uri 'self'; script-src 'self' 'unsafe-inline' 'unsafe-eval' blob:; worker-src 'self' blob:");return h;}
 private WebResourceResponse missing(){return new WebResourceResponse("text/plain","UTF-8",404,"Not Found",Collections.emptyMap(),new ByteArrayInputStream(new byte[0]));}
 private void message(String s){runOnUiThread(()->Toast.makeText(this,s,Toast.LENGTH_LONG).show());}
 private void external(Uri u){if(!"https".equals(u.getScheme())&&!"mailto".equals(u.getScheme()))return;try{startActivity(new Intent(Intent.ACTION_VIEW,u).addCategory(Intent.CATEGORY_BROWSABLE));}catch(Exception e){message("No hay aplicación disponible para abrir este enlace.");}}
 private void captureReturn(Intent i){Uri u=i.getData();if(u!=null&&"sofcal".equals(u.getScheme())&&"oauth".equals(u.getHost())&&u.toString().length()<1200)pendingReturn=u.toString();}
 @Override protected void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);captureReturn(i);deliverReturn();}
 private void deliverReturn(){if(ready&&pendingReturn!=null){String value=pendingReturn;pendingReturn=null;web.evaluateJavascript("(function attempt(n){if(window.sofcalAndroidReturn45){window.sofcalAndroidReturn45("+JSONObject.quote(value)+");}else if(n<50){setTimeout(function(){attempt(n+1)},100);}})(0)",null);}}
 public final class Bridge {
  @JavascriptInterface public void closeApp(){runOnUiThread(()->finish());}
  @JavascriptInterface public void openExternal(String url){if(url!=null&&url.length()<5000)runOnUiThread(()->external(Uri.parse(url)));}
  @JavascriptInterface public void saveFile(String data,String name,String mime){if(data==null||data.length()>33000000){message("Archivo demasiado grande para guardar.");return;}runOnUiThread(()->{if(pendingSave!=null){message("Termine de guardar el archivo anterior.");return;}try{pendingSave=Base64.decode(data,Base64.DEFAULT);String filename=(name==null?"SOF-CAL":name).replaceAll("[\\\\/:*?\"<>|]","-");Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(mime==null?"application/octet-stream":mime).putExtra(Intent.EXTRA_TITLE,filename);startActivityForResult(i,62);}catch(Exception e){pendingSave=null;message("No se pudo preparar el archivo.");}});}
 }
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==61&&picker!=null){picker.onReceiveValue(WebChromeClient.FileChooserParams.parseResult(result,data));picker=null;}if(request==62){byte[] bytes=pendingSave;pendingSave=null;if(result==RESULT_OK&&data!=null&&data.getData()!=null&&bytes!=null){Uri uri=data.getData();new Thread(()->{try(OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException();out.write(bytes);message("Archivo guardado.");}catch(Exception e){message("No se pudo guardar. Exporte de nuevo el archivo.");}}).start();}}}
 @Override public void onBackPressed(){if(web.canGoBack())web.goBack();else new AlertDialog.Builder(this).setMessage("¿Salir de SOF-CAL? Los borradores guardados permanecen en este dispositivo.").setNegativeButton("Continuar",null).setPositiveButton("Salir",(d,w)->web.evaluateJavascript("(async function(){try{if(typeof Portal!=='undefined')await Portal.flush();if(typeof App!=='undefined'&&App.insp&&typeof saveNow==='function'&&!ro())await saveNow();SofcalAndroid.closeApp();}catch(e){alert('No se pudo terminar de guardar. Permanezca en la app y revise el registro.');}})()",null)).show();}
 @Override protected void onDestroy(){if(picker!=null)picker.onReceiveValue(null);web.destroy();super.onDestroy();}
}
